from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
jobs=json.loads((ROOT/'image_jobs.json').read_text())
specs={
 'CS23':'''Use case: precise-object-edit. Correct the assembly geometry in this CS23 sheet while preserving its style, neutral background, component language and two separate local clusters. CRITICAL: the barred gate must stand ON TOP of the fixed causeway walking deck and block that same horizontal walk route. Currently the gate incorrectly descends below the deck into water. Replace the left cluster and its matching detail views with a continuous flat stone causeway passing THROUGH the gate opening at deck height. In closed pose, bars stand from deck level upward within a tall static frame. Their open travel is vertically UP above the opening; there is no water tunnel under the gate, no lowering bridge and no new lower route. The causeway continues visibly behind it. Gate and rails stay outside/around a clear continuous walking strip. Water is below bridge edges only. On the right cluster preserve the modest wheel, drum and floor-chain guide, but replace the big doorway-looking storage door with a plain closed stone wall and shallow shelf so it cannot imply an extra route. Keep the diagrammatic connection line clearly detached from actual map placement. The two clusters are art assemblies, not a new map layout. Header remains CS23 / WholeSectionAssembly. Do not add new mechanisms.''',
 'CS24':'''Use case: precise-object-edit. Change only the camera presentation in this matched two-panel CS24 art sheet: convert the TWO top panels to FIRST-PERSON player views. Remove the full external chef standing on the bridge from both panels. Instead place a small low-poly mitten/glove holding a lantern at the same lower-left screen edge in each panel, like a first-person game view. Maintain the SAME camera height, framing, gate, continuous fixed deck, rails, bank geometry, background, lighting and closed/open state between the pair. Left bars down, right leaf parked vertically above the opening. No third-person full body. Preserve all bottom isolated model views, labels, style and layout. Keep both panels matched; no new objects, new route or drawbridge motion.''',
 'CS26':'''Use case: text-localization. Correct only the component catalog ID labels in this existing CS26 sheet; keep every object, layout, background, light and other caption unchanged. All ChainGuide_Open views use CCS29, not CCS01. ChainGuide_Corner uses CCS28, not CCS02. FloorChain uses CCS27, not CCS03. CellarWall_Segment views use CCS15, not CCS04. StoneFloor_Tiles uses CCS13, not CCS05. MaintenanceShelf_Set uses CCS69, not CCS06. WallLantern uses CCS60, not CCS07. Player_Lantern_Ref must have the label "CONTEXT ONLY" instead of CCS08; it is an existing pickup reference, not a new catalog model. Apply the corrected ID consistently to all repeated views of that item. The title remains CS26 / CellarChainTellAndMaintenanceBay. Text correction only.'''}
for ident,prompt in specs.items():
    j=next(j for j in jobs if j['id']==ident)
    if 'revision_reference' not in j:j['revision_reference']=j['image']
    j['image']=j['revision_reference'].replace('.png','-r02.png')
    j['edit_prompt']=f'prompts/{ident}_r02-edit.txt'
    (ROOT/j['edit_prompt']).write_text(prompt+'\n')
(ROOT/'image_jobs.json').write_text(json.dumps(jobs,indent=2)+'\n')
print(json.dumps([dict(id=j['id'],prompt=(ROOT/j['edit_prompt']).read_text(),reference=str(ROOT/j['revision_reference'])) for j in jobs if j['id'] in specs]))
